    filtrarTipoAnotacao: function (chk, opcaoId) {
        var tiposAnotacaoItens = null;
        this._toolbar.items.items.forEach(function(item){
            if(item.text == 'Filtros'){
                item.menu.items.items.forEach(function(itemMenu){
                    if(itemMenu.name == 'tipos_anotacao'){
                        tiposAnotacaoItens = itemMenu.menu.items.items;
                    }
                });
            }
        });

        if(opcaoId == 'TodosTiposAnotacao' && !chk.checked == true){
            tiposAnotacaoItens.forEach(function(itemMenuTipoAnotacao){
                if(itemMenuTipoAnotacao.text != 'TodosTiposAnotacao'){ itemMenuTipoAnotacao.setChecked(false); }
            });

            this.removeFilterProperty('tipo__in', 1, true);
        }else if(opcaoId == 'TodosTiposAnotacao' && !chk.checked == false){
            var itemTipoAnotacao =  tiposAnotacaoItens[1];
            itemTipoAnotacao.setChecked(true);
            
            var tipoAnotId = itemTipoAnotacao.id.split('_')[1];
            this.setFilterProperty('tipo__in', [tipoAnotId], 1, true);
        }else{
            var itensTiposAnotacaoFiltrar = !chk.checked == true ? [opcaoId] : [];
            tiposAnotacaoItens.forEach(function(itemTipoAnotacao){
                if(itemTipoAnotacao.id == 'TodosTiposAnotacao'){
                    itemTipoAnotacao.setChecked(false);
                }else if(itemTipoAnotacao.id != 'TodosTiposAnotacao'){
                    var tipoAnotId = itemTipoAnotacao.id.split('_')[1];                    
                    if(tipoAnotId != opcaoId && itemTipoAnotacao.checked == true){
                        itensTiposAnotacaoFiltrar.push(tipoAnotId);
                    }
                }
            });
            if(itensTiposAnotacaoFiltrar.length > 0){
                this.setFilterProperty('tipo__in', itensTiposAnotacaoFiltrar, 1, true);
            }else{
                tiposAnotacaoItens.forEach(function(itemTipoAnotacao){
                    if(itemTipoAnotacao.id == 'TodosTiposAnotacao'){
                        itemTipoAnotacao.setChecked(true);
                    }else{
                        var tipoAnotId = itemTipoAnotacao.id.split('_')[1];
                        if(tipoAnotId != opcaoId){ itemTipoAnotacao.setChecked(false); }
                    }
                });
                this.removeFilterProperty('tipo__in', 1, true);
            }
        }
    },

