    ocultarAnotacao: function(cfg) {
        var selected = this.getSelectionModel().getSelected();
        if (selected) {
            if( selected.json.situacao === 'Removido'){
                Ext.Msg.show({
                    title:'Aviso!',
                    msg: 'Anotação Selecionada já foi ocultada.',
                    icon: Ext.Msg.INFO,
                    buttons: Ext.Msg.OK
                })
            }
            else{
                var msg = 'Tem certeza que deseja ocultar a anotação selecionada ?';
                var params = {
                    'anotacao_pk': selected.id,
                }
                
                Ext.Msg.show({
                msg: msg,
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function (b) {
                    if (b == 'no') return;

                    params = params;
                    this._realizarReq(params, 'AnotacaoPessoalCadRF', 'ocultar_anotacao');
                }
            });
            }
        } else Ext.Msg.show({
            msg: 'Selecione a Anotação que será ocultada.',
            icon: Ext.Msg.ERROR,
            buttons: Ext.Msg.OK
        })
    },

    _realizarReq: function(params, nome_classe, nome_metodo){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(nome_classe,nome_metodo),
            params: params,
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                var icon = obj.success == true ? Ext.Msg.INFO : Ext.Msg.ERROR;
                Ext.Msg.show({
                    width:"400px",
                    title: this.title,
                    icon: icon,
                    buttons: Ext.Msg.OK,
                    msg: obj.message
                });
                if(obj.success == true){ this.getStore().reload(); }
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },

